function T(e, d, l) {
  let o = { explanation: { type: "string", description: "Tooltip body text. Explain what the user is looking at and why it matters. This is the ONLY place the user sees your words \u2014 be complete but concise." }, next_preview: { type: "string", description: `One line describing exactly what will happen when the user clicks Next. Example: "Next: I'll click Create Bucket and type the name." Shown below the explanation in a smaller font.` }, anchor: { type: "array", items: { type: "number" }, minItems: 2, maxItems: 2, description: `(x, y) \u2014 where the tooltip arrow points. ${e.x} Omit to center the tooltip with no arrow (for general-context steps).` }, actions: { type: "array", items: l, description: "Actions to execute when the user clicks Next. Same item schema as computer_batch.actions. Empty array is valid for purely explanatory steps. Actions run sequentially and stop on first error." } };
  return [{ name: "request_teach_access", description: 'Request permission to guide the user through a task step-by-step with on-screen tooltips. Use this INSTEAD OF request_access when the user wants to LEARN how to do something (phrases like "teach me", "walk me through", "show me how", "help me learn"). On approval the main Claude window hides and a fullscreen tooltip overlay appears. You then call teach_step repeatedly; each call shows one tooltip and waits for the user to click Next. Same app-allowlist semantics as request_access, but no clipboard/system-key flags. Teach mode ends automatically when your turn ends.', inputSchema: { type: "object", properties: { apps: { type: "array", items: { type: "string" }, description: d }, reason: { type: "string", description: 'What you will be teaching. Shown in the approval dialog as "Claude wants to guide you through {reason}". Keep it short and task-focused.' } }, required: ["apps", "reason"] } }, { name: "teach_step", description: "Show one guided-tour tooltip and wait for the user to click Next. On Next, execute the actions, take a fresh screenshot, and return both \u2014 you do NOT need a separate screenshot call between steps. The returned image shows the state after your actions ran; anchor the next teach_step against it. IMPORTANT \u2014 the user only sees the tooltip during teach mode. Put ALL narration in `explanation`. Text you emit outside teach_step calls is NOT visible until teach mode ends. Pack as many actions as possible into each step's `actions` array \u2014 the user waits through the whole round trip between clicks, so one step that fills a form beats five steps that fill one field each. Returns {exited:true} if the user clicks Exit \u2014 do not call teach_step again after that. Take an initial screenshot before your FIRST teach_step to anchor it.", inputSchema: { type: "object", properties: o, required: ["explanation", "next_preview", "actions"] } }, { name: "teach_batch", description: "Queue multiple teach steps in one tool call. Parallels computer_batch: N steps \u2192 one model\u2194API round trip instead of N. Each step still shows a tooltip and waits for the user's Next click, but YOU aren't waiting for a round trip between steps. You can call teach_batch multiple times in one tour \u2014 treat each batch as one predictable SEGMENT (typically: all the steps on one page). The returned screenshot shows the state after the batch's final actions; anchor the NEXT teach_batch against it. WITHIN a batch, all anchors and click coordinates refer to the PRE-BATCH screenshot (same invariant as computer_batch) \u2014 for steps 2+ in a batch, either omit anchor (centered tooltip) or target elements you know won't have moved. Good pattern: batch 5 tooltips on page A (last step navigates) \u2192 read returned screenshot \u2192 batch 3 tooltips on page B \u2192 done. Returns {exited:true, stepsCompleted:N} if the user clicks Exit \u2014 do NOT call again after that; {stepsCompleted, stepFailed, ...} if an action errors mid-batch; otherwise {stepsCompleted, results:[...]} plus a final screenshot. Fall back to individual teach_step calls when you need to react to each intermediate screenshot.", inputSchema: { type: "object", properties: { steps: { type: "array", minItems: 1, items: { type: "object", properties: o, required: ["explanation", "next_preview", "actions"] }, description: "Ordered steps. Validated upfront \u2014 a typo in step 5 errors before any tooltip shows." } }, required: ["steps"] } }];
}
